import{af as t,z as a,J as o,ab as r}from"./chunks/framework.ss42i_gG.js";const c=JSON.parse('{"title":"How to use the power budget feature on the LightBug App","description":"","frontmatter":{"aside":false,"sidebar":false,"editLink":false},"headers":[],"relativePath":"guides/power-budget-app.md","filePath":"guides/power-budget-app.md"}'),i={name:"guides/power-budget-app.md"};function s(d,e,l,n,p,h){return a(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793282371000"},[...e[0]||(e[0]=[r('<h1 id="how-to-use-the-power-budget-feature-on-the-lightbug-app" tabindex="-1">How to use the power budget feature on the LightBug App <a class="header-anchor" href="#how-to-use-the-power-budget-feature-on-the-lightbug-app" aria-label="Permalink to &quot;How to use the power budget feature on the LightBug App&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>If you find that the battery of your device is draining too quickly, we recommend enabling the power budget feature.</p></div><h2 id="what-is-the-power-budget-feature" tabindex="-1">What is the power budget feature? <a class="header-anchor" href="#what-is-the-power-budget-feature" aria-label="Permalink to &quot;What is the power budget feature?&quot;">​</a></h2><p>This feature allows a certain amount of power to be used when <code>transmitting</code>, so if the conditions are not so great and the tracker has to use a lot of power to transmit, it will ignore the location update and try again later if the conditions are better.</p><p>Examples of where this will be useful are:</p><ol><li>In very low signal areas i.e. underground parking, rural areas</li><li>If the tracker is in a metal container i.e. delivery vehicle, cargo ship</li><li>For any other scenario where the tracker uses too much time for a single transmission</li></ol><h2 id="how-do-i-apply-the-power-budget-feature" tabindex="-1">How do I apply the power budget feature? <a class="header-anchor" href="#how-do-i-apply-the-power-budget-feature" aria-label="Permalink to &quot;How do I apply the power budget feature?&quot;">​</a></h2><ol><li>On the app go to Menu - &#39;Tracker Settings&#39;<br><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043169226361-2cnE-VjXINy_XRAH_9ZtOMULD0MvpdLjcA.png" alt="" width="250"></li><li>On step 1 select &#39;Manual Configuration&#39;<br><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043169226359-chdclsONqjUrbNIIZev28s8GSbnV3Yev1w.png" alt="" width="250"></li><li>Scroll down to the bottom of the page and select &#39;Advanced Settings - Change at your own risk&#39;. More advanced settings will appear.<br><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043171233804-eC69ALcU9dooQ7xbXTrdpHahPkBYlPeclA.png" alt="" width="250"></li><li>Go to &#39;Power Budget&#39; and enable the power power budget feature so that the toggle is orange. <img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043171236169-hdMQXnwzkj2lIcqcpUlQ1CGngGXCRuLRxw.png" alt="" width="250"></li><li>After enabling power budgeting the &#39;Budget Mode&#39; option will appear. Upon pressing the drop down arrow, a box will appear, here you have to set your preferred mode. The percentages show how many location updates might be dropped in average conditions.<br><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043171257084-ny4dBfmE5QqUVTOuSrT-luqhRfL4wqjTTA.png" alt="" width="250"></li><li>Review the settings and then select &#39;save&#39;.<br><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043171260697-01TpXsoC4df-iiHOGos_FFXL8VtqxNBlDw.png" alt="" width="250"></li></ol><div class="tip custom-block"><p class="custom-block-title">⚡ Tip</p><p>To apply the new settings immediately, press the button on your tracker. If you don&#39;t have your tracker to hand, the tracker will update its settings the next time it is scheduled to send a location update.</p></div><p>If you can&#39;t find the information you&#39;re looking for, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">get in touch!</a></p>',10)])])}const g=t(i,[["render",s]]);export{c as __pageData,g as default};
